REPORT_CATALOGS: dict[str, dict[str, str]] = {
    code: dict(zip(REPORT_KEYS, row.split("|"), strict=True))
    for code, row in REPORT_ROWS.items()
}

_EXPECTED_LOCALES = {code for code, _ in LANGUAGE_OPTIONS if code != "en"} | {
    "ha"
}
if set(REPORT_CATALOGS) != _EXPECTED_LOCALES:
    raise ValueError("Report catalog locale coverage is incomplete")
if len(REPORT_KEYS) != len(set(REPORT_KEYS)):
    raise ValueError("Report catalog has duplicate source keys")
_formatter = string.Formatter()
for _locale, _entries in REPORT_CATALOGS.items():
    if set(_entries) != set(REPORT_KEYS):
        raise ValueError("Report catalog source coverage is incomplete")
    for _source, _value in _entries.items():
        if not _value.strip():
            raise ValueError("Report catalog contains an empty translation")
        _source_slots = Counter(
            name
            for _, name, _, _ in _formatter.parse(_source)
            if name is not None
        )
        _value_slots = Counter(
            name
            for _, name, _, _ in _formatter.parse(_value)
            if name is not None
        )
        if _source_slots != _value_slots:
            raise ValueError("Report catalog named slots differ from source")
